import logging
from functools import wraps

logging.basicConfig(level=logging.WARNING, format="%(levelname)s:%(message)s")
logger = logging.getLogger(__name__)

DEPRECATION_MESSAGE = (
    "The function {keyword_name} is deprecated and will no longer be maintained. "
    "Consider avoiding its use or contact support if enhancements are required."
)


def deprecated():
    """This is a decorator which can be used to mark functions as deprecated.
    It will result in a warning being logged when the function is used."""

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            logger.warning(DEPRECATION_MESSAGE.format(keyword_name=func.__name__))
            return func(*args, **kwargs)

        return wrapper

    return decorator
